urlset:
{% for article in articles %}

        https://www.themetacity.com{{ url_for('blog.title', url=article.url) }}
        {{ article.update_date.strftime('%Y-%m-%d') }}
        never

{% endfor %}


    https://www.themetacity.com{{ url_for('blog.tags') }}
    monthly


